# Cars 4: bike stays upright (AlignOrientation, wider hidden track), gentler pull (0.16 g), spawn faces an open lane.
import base64, zlib, os, sys, json
FULL = {
"src/ServerScriptService/MTL/Services/Chassis.lua": [
14640,
""
],
"src/ServerScriptService/MTL/Services/VehicleService.lua": [
21136,
""
]
}
PAIRS = {}
NEW_MAN = []
out, bad = {}, []
for path, (size, blob) in FULL.items():
    if size == -1:
        if os.path.exists(path): bad.append("%s: already exists" % path); continue
    elif not os.path.exists(path) or os.path.getsize(path) != size:
        bad.append("%s: size mismatch" % path); continue
    out[path] = zlib.decompress(base64.b64decode(blob))
for path, ps in PAIRS.items():
    s = open(path, encoding="utf-8").read()
    for a, b, n in ps:
        c = s.count(a)
        if c != n:
            bad.append("%s: expected %d of %r, found %d" % (path, n, a[:70], c)); continue
        s = s.replace(a, b)
    out[path] = s.encode("utf-8")
m = "tools/manifest.json"
man = json.load(open(m))
have = {e.get("file") for e in man}
add = [e for e in NEW_MAN if e["file"] not in have]
if add:
    man.extend(add)
    out[m] = (json.dumps(man, indent=1) + "\n").encode()
if bad:
    print("NOT APPLIED:")
    for x in bad: print(" -", x)
    sys.exit(1)
for path, data in out.items():
    open(path, "wb").write(data)
    print("wrote", path, len(data))
